def format_prompt_for_printing(prompt_data) -> str:
    """Format prompt messages for debug printing."""
    if not prompt_data:
        return "(no prompt)"

    result = ""
    if isinstance(prompt_data, list):
        for msg in prompt_data:
            if isinstance(msg, dict):
                role = msg.get("role", "unknown")
                content = msg.get("content", "")
                result += f"**{role.upper()}**:\n{content}\n\n"
    return result

def get_config_bool(config, key, default=False):
    value = OmegaConf.select(config, key, default=default)
    if isinstance(value, str):
        return value.strip().lower() in {"1", "true", "yes", "y", "on"}
    return bool(value)

def is_prompt_too_long_error(exc):
    text = str(exc)
    return "sequence_length=" in text and "larger than max_length=" in text

def build_search_user_content(query, docs):
    return (
        f"**Current Sub-question**: {query}\n\n"
        f"**Search Context**:\n" + "\n".join(docs)
    )

def compact_phase2_messages(messages):
    """Drop old search documents while preserving previous sub-questions and conclusions."""
    compacted = []
    for msg in messages:
        msg = dict(msg)
        content = msg.get("content", "")
        if msg.get("role") == "user" and "**Search Context**:" in content:
            prefix = content.split("**Search Context**:", 1)[0].rstrip()
            msg["content"] = f"{prefix}\n\n**Search Context**:\n[omitted from previous turn]"
        compacted.append(msg)
    return compacted

def truncate_docs_for_prompt(docs, max_chars=MAX_FALLBACK_DOC_CHARS):
    truncated = []
    for doc in docs:
        doc = str(doc)
        if len(doc) > max_chars:
            doc = doc[:max_chars].rstrip() + "\n[...truncated...]"
        truncated.append(doc)
    return truncated

def flatten_answer_candidates(answer):
    """Return plain answer strings from scalar/list/array ground-truth values."""
    if isinstance(answer, dict):
        answer = answer.get("target", answer.get("answer", answer))
    if hasattr(answer, "tolist"):
        answer = answer.tolist()
    if isinstance(answer, (list, tuple, set)):
        candidates = []
        for item in answer:
            candidates.extend(flatten_answer_candidates(item))
        return candidates
    if answer is None:
        return []
    answer = str(answer).strip()
    return [answer] if answer else []

def unwrap_singleton(value):
    if isinstance(value, np.ndarray):
        if value.size == 1:
            return unwrap_singleton(value.reshape(-1)[0])
        return value.tolist()
    if isinstance(value, (list, tuple)) and len(value) == 1:
        return unwrap_singleton(value[0])
    return value

def is_binary_answer(answer):
    candidates = flatten_answer_candidates(answer)
    return bool(candidates) and all(normalize_answer(candidate) in BINARY_ANSWERS for candidate in candidates)

def compute_final_answer_reward(final_ans, answer, em_weight=0.0):
    candidates = flatten_answer_candidates(answer) or [""]
    scores = compute_scores([final_ans], [candidates])
    if is_binary_answer(candidates):
        return scores["em"]

    em_weight = float(em_weight)
    if not 0.0 <= em_weight <= 1.0:
        raise ValueError(f"final answer EM weight must be in [0, 1], got {em_weight}")
    return em_weight * scores["em"] + (1.0 - em_weight) * scores["f1"]

def count_answer_hits(docs, answer):
    candidates = [
        normalize_answer(candidate)
        for candidate in flatten_answer_candidates(answer)
        if str(candidate).strip()
    ]
    if not candidates:
        return 0
    hits = 0
    for doc in docs:
        normalized_doc = normalize_answer(str(doc))
        if any(candidate and candidate in normalized_doc for candidate in candidates):
            hits += 1
    return hits

def nrpsc_tiebreak_signal(question, answer, intermediate_results):
    """NR-PSC tie-break signal: did any document retrieved anywhere in this workflow contain a gold answer string?

    Returns ``(usable, hit)``. ``usable`` is False (and ``hit`` meaningless) for yes/no answers, where "retrieved"
    is not a meaningful check, and for answers that are themselves a substring of the question (the check would be
    trivially satisfied by the question text alone, not by anything the Planner's search actually found). This is
    a *secondary* signal: it only ever breaks a class-comparison tie on the primary EM outcome, so a question the
    EM comparison already decides is unaffected regardless of this function's result.
    """
    if is_binary_answer(answer):
        return False, False
    candidates = [normalize_answer(candidate) for candidate in flatten_answer_candidates(answer)
                  if str(candidate).strip()]
    candidates = [candidate for candidate in candidates if candidate]
    if not candidates:
        return False, False
    normalized_question = normalize_answer(str(question))
    if any(candidate in normalized_question for candidate in candidates):
        return False, False
    docs = []
    for info in intermediate_results.values():
        docs.extend(info.get("docs") or [])
    return True, count_answer_hits(docs, answer) > 0

SUBGOAL_METRIC_KEYS = ("subgoal_steps", "subgoal_memory_steps", "subgoal_search_steps", "summary_fallback")


def subgoal_summary_metrics(prefix, lists):
    """Per-workflow means of the Subgoal Plan v1 counters, plus the share of steps answered without retrieval."""
    if not lists["subgoal_steps"]:
        return {}
    steps = float(np.sum(lists["subgoal_steps"]))
    executed = float(np.sum(lists["subgoal_memory_steps"]) + np.sum(lists["subgoal_search_steps"]))
    return {
        f"{prefix}/subgoal/steps_mean": float(np.mean(lists["subgoal_steps"])),
        f"{prefix}/subgoal/memory_steps_mean": float(np.mean(lists["subgoal_memory_steps"])),
        f"{prefix}/subgoal/search_steps_mean": float(np.mean(lists["subgoal_search_steps"])),
        f"{prefix}/subgoal/memory_step_share": float(np.sum(lists["subgoal_memory_steps"]) / executed) if executed else 0.0,
        f"{prefix}/subgoal/summary_fallback_rate": float(np.mean(lists["summary_fallback"])),
        f"{prefix}/subgoal/planned_steps_total": steps,
    }


def compute_response_mask(data: DataProto):
    """Compute the attention mask for the response part of the sequence.

    This function extracts the portion of the attention mask that corresponds to the model's response,
    which is used for masking computations that should only apply to response tokens.

    Args:
        data (DataProto): The data containing batched model outputs and inputs.

    Returns:
        torch.Tensor: The attention mask for the response tokens.
    """
    responses = data.batch["responses"]
    response_length = responses.size(1)
    attention_mask = data.batch["attention_mask"]
    return attention_mask[:, -response_length:]

class WorkflowRolloutMixin:
    """Workflow (multi-agent DAG) rollout, reward assignment and single-step inference, taken verbatim from JADE."""

    def async_rollout_batch(self, batch_dict, qa_manager, max_workers=4, parallel=True, show_process=False):
        """
        鎵归噺 rollout锛屾敮鎸佷覆琛屼笌骞惰妯″紡銆?
        Args:
            batch_dict: 杈撳叆鎵归噺鏁版嵁
            qa_manager: QA 绠＄悊鍣?            parallel (bool): 鏄惁鍚敤骞惰妯″紡
            max_workers (int): 骞惰绾跨▼鏁伴噺锛坧arallel=True 鐢熸晥锛?        """
        self._check_slim_rollout_config()
        questions = [item['question'] for item in batch_dict['extra_info']]
        answers = [item['answer'] for item in batch_dict['extra_info']]
        workflow_rollout_n = int(OmegaConf.select(self.config, "qa_manager.workflow_rollout_n", default=1))
        if workflow_rollout_n < 1:
            raise ValueError(f"qa_manager.workflow_rollout_n must be positive, got {workflow_rollout_n}")
        advantage_estimator = self.config.algorithm.adv_estimator
        if isinstance(advantage_estimator, AdvantageEstimator):
            advantage_estimator = advantage_estimator.value
        if advantage_estimator != AdvantageEstimator.WORKFLOW_RLOO.value:
            raise NotImplementedError(
                f"only workflow_rloo is kept in this slimmed rollout, got {advantage_estimator}"
            )
        if workflow_rollout_n < 2:
            raise ValueError("workflow_rloo requires qa_manager.workflow_rollout_n >= 2")
        batch: DataProto = DataProto.from_single_dict(batch_dict)

        if show_process and as_agent_dict is not None:
            questions = [questions[0]]
            answers = [answers[0]]
            workflow_rollout_n = 1

        def select_item_keep_dim(batch_dict, idx):
            """
            浠?batch_dict 鎻愬彇鎸囧畾 idx 鐨勬暟鎹紝浣嗕繚鐣?batch 缁村害 = 1锛?            鍚屾椂淇濊瘉鏍煎紡涓庡師濮?batch_dict 鐩稿悓銆?            """
            item_dict = {}
            for key, value in batch_dict.items():
                if isinstance(value, torch.Tensor):
                    item_dict[key] = value[idx:idx+1]
                elif isinstance(value, np.ndarray):
                    item_dict[key] = value[idx:idx+1]
                elif isinstance(value, list):
                    item_dict[key] = [value[idx]]
                else:
                    try:
                        item_dict[key] = value[idx:idx+1]
                    except Exception:
                        item_dict[key] = value
            return item_dict

        # A. 鍞ら啋妯″瀷锛堜竴娆★級
        if self.config.actor_rollout_ref.rollout.free_cache_engine:
            self.async_rollout_manager.wake_up()

        batch_list, final_em_list = [], []
        turn_number_list, retrieval_times_list = [], []
        planned_search_nodes_list, planned_reason_nodes_list = [], []
        summary_first_valid_list, summary_retry_used_list = [], []
        workflow_valid_list = []
        data_sources_by_question = {}
        rewards_by_question = defaultdict(list)
        ems_by_question = defaultdict(list)
        subgoal_lists = {key: [] for key in SUBGOAL_METRIC_KEYS}
        record_metrics_batch = {
            'times': {
                agent: []
                for agent in ['PlanningAgent', 'QueryRewriteAgent', 'ReasonerAgent', 'AnswerSummarizationAgent', 'AnswerGenerationAgent']
            }
        }

        # 鍖呰鍗曟潯浠诲姟閫昏緫
        def process_single_item(item_id, sample_id, question, answer):
            item_dict = select_item_keep_dim(batch_dict, item_id)
            item_batch_list, record_metrics = self.async_rollout_single(
                qa_manager, item_dict, question, answer, show_process
            )

            question_uid = f"step-{self.global_steps}-question-{item_id}"
            trajectory_id = f"{question_uid}-workflow-{sample_id}"
            for data in item_batch_list:
                row_count = data.batch.batch_size[0]
                data.non_tensor_batch['uid'] = np.full(row_count, question_uid, dtype=object)
                data.non_tensor_batch['trajectory_id'] = np.full(row_count, trajectory_id, dtype=object)
                data.non_tensor_batch['workflow_sample'] = np.full(row_count, sample_id, dtype=np.int64)

            return item_batch_list, record_metrics

        def collect_record_metrics(item_id, sample_id, item_batch_list, record_metrics):
            batch_list.extend(item_batch_list)
            data_sources_by_question[item_id] = record_metrics.get(
                "data_source", "unknown"
            )
            final_em = record_metrics.get('final_em', 0.0)
            final_em_list.append(final_em)
            ems_by_question[item_id].append(final_em)
            rewards_by_question[item_id].append(record_metrics.get('final_reward', record_metrics['final_f1']))
            turn_number_list.append(record_metrics['turn_number'])
            retrieval_times_list.append(record_metrics['retrieval_times'])
            planned_search_nodes_list.append(record_metrics['planned_search_nodes'])
            planned_reason_nodes_list.append(record_metrics['planned_reason_nodes'])
            workflow_valid_list.append(record_metrics['workflow_valid'])
            if record_metrics['summary_attempted']:
                summary_first_valid_list.append(record_metrics['summary_first_valid'])
                summary_retry_used_list.append(record_metrics['summary_retry_used'])
            for key in subgoal_lists:
                subgoal_lists[key].append(record_metrics.get(key, 0))

            for agent_name in ['PlanningAgent', 'QueryRewriteAgent', 'ReasonerAgent', 'AnswerSummarizationAgent', 'AnswerGenerationAgent']:
                record_metrics_batch['times'][agent_name].append(record_metrics['times'][agent_name])

        if parallel:
            logging.info(f"Using parallel rollout with max_workers={max_workers}")
            with ThreadPoolExecutor(max_workers=max_workers) as executor:
                future_to_id = {}
                for item_id, (question, answer) in enumerate(zip(questions, answers)):
                    for sample_id in range(workflow_rollout_n):
                        future = executor.submit(process_single_item, item_id, sample_id, question, answer)
                        future_to_id[future] = (item_id, sample_id)
                # for future in tqdm(as_completed(future_to_id), total=len(questions)):
                for future in as_completed(future_to_id):
                    item_id, sample_id = future_to_id[future]
                    try:
                        item_batch_list, record_metrics = future.result()
                        collect_record_metrics(
                            item_id,
                            sample_id,
                            item_batch_list,
                            record_metrics,
                        )
                        # 鏀堕泦鏁版嵁
                        # 缁熻workflow绫诲瀷
                    except Exception as e:
                        logging.error(f"Error in item {item_id}, workflow sample {sample_id}: {e!r}", exc_info=True)  # SIPPO: logging only
        else:
            logging.info("Using sequential rollout")
            for item_id, (question, answer) in enumerate(tqdm(zip(questions, answers), total=len(questions))):
                for sample_id in range(workflow_rollout_n):
                    item_batch_list, record_metrics = process_single_item(item_id, sample_id, question, answer)
                    collect_record_metrics(
                        item_id,
                        sample_id,
                        item_batch_list,
                        record_metrics,
                    )
        # 璁＄畻鏈€缁?train metrics
        if not batch_list:
            raise RuntimeError("all workflow rollouts failed; no training samples were produced")

        completed_rollouts = len(final_em_list)
        incomplete_question_groups = sum(
            len(rewards_by_question.get(item_id, [])) != workflow_rollout_n
            for item_id in range(len(questions))
        )
        best_reward_by_question = [max(rewards) for rewards in rewards_by_question.values() if rewards]
        best_em_by_question = [max(values) for values in ems_by_question.values() if values]
        all_final_rewards = [reward for rewards in rewards_by_question.values() for reward in rewards]
        reward_std_by_question = [np.std(rewards) for rewards in rewards_by_question.values() if len(rewards) > 1]
        em_std_by_question = [np.std(values) for values in ems_by_question.values() if len(values) > 1]

        train_reward_metrics = {
            "train/workflow/turns_mean": np.mean(turn_number_list),
            "train/workflow/retrieval_calls_mean": np.mean(retrieval_times_list),
            "train/workflow/planned_search_nodes_mean": np.mean(planned_search_nodes_list),
            "train/workflow/planned_reason_nodes_mean": np.mean(planned_reason_nodes_list),
            "train/workflow/summary_first_valid_rate": (
                np.mean(summary_first_valid_list) if summary_first_valid_list else 0.0
            ),
            "train/workflow/summary_retry_rate": (
                np.mean(summary_retry_used_list) if summary_retry_used_list else 0.0
            ),
            "train/workflow/valid_rate": np.mean(workflow_valid_list),
            "train/rollout/em_aggregate": np.mean(final_em_list),
            "train/rollout/optimization_reward_after_constraints": np.mean(all_final_rewards),
            "train/rollout/best_of_n_em": np.mean(best_em_by_question),
            "train/rollout/best_of_n_optimization_reward": np.mean(best_reward_by_question),
            "train/rollout/within_question_em_std": (
                np.mean(em_std_by_question) if em_std_by_question else 0.0
            ),
            "train/rollout/within_question_optimization_reward_std": (
                np.mean(reward_std_by_question) if reward_std_by_question else 0.0
            ),
            "train/workflow/completed": completed_rollouts,
            "train/workflow/incomplete_question_groups": incomplete_question_groups,
        }
        if self._plan_format() == "subgoal":
            train_reward_metrics.update(subgoal_summary_metrics("train", subgoal_lists))
        data_source_question_counts = defaultdict(int)
        for data_source in data_sources_by_question.values():
            data_source_question_counts[str(data_source)] += 1
        for data_source, count in sorted(data_source_question_counts.items()):
            train_reward_metrics[f"train/data/questions/{data_source}"] = count
        for agent_name in ['PlanningAgent', 'QueryRewriteAgent', 'ReasonerAgent', 'AnswerSummarizationAgent', 'AnswerGenerationAgent']:
            values = record_metrics_batch['times'][agent_name]
            if values:
                train_reward_metrics[f"train/agent_calls/{agent_name}"] = np.mean(values)

        # B. 鎵ц缁撴潫鍚?sleep
        if self.config.actor_rollout_ref.rollout.free_cache_engine:
            self.async_rollout_manager.sleep()

        return batch_list, train_reward_metrics

    def async_rollout_single(
        self,
        qa_manager,
        target_dict,
        question,
        answer,
        show_process=False,
    ):
        # result_reward_only=true is enforced by _check_slim_rollout_config: every step's reward is the final reward.
        print_invalid_rollouts = get_config_bool(self.config, "qa_manager.print_invalid_rollouts", default=False)
        final_reward_em_weight = float(
            OmegaConf.select(self.config, "qa_manager.final_reward_em_weight", default=0.0)
        )
        require_grounded_final = get_config_bool(
            self.config, "qa_manager.require_grounded_final", default=False
        )
        invalid_workflow_reward_cap = float(
            OmegaConf.select(self.config, "qa_manager.invalid_workflow_reward_cap", default=0.0)
        )
        retrieval_topk = int(OmegaConf.select(self.config, "qa_manager.retrieval_topk", default=ROSA_TOPK))
        max_nodes_per_turn = int(
            OmegaConf.select(self.config, "qa_manager.max_nodes_per_turn", default=MAX_NODES_PER_TURN)
        )
        search_rewrite_max_retries = int(
            OmegaConf.select(
                self.config,
                "qa_manager.search_rewrite_max_retries",
                default=SEARCH_REWRITE_MAX_RETRIES,
            )
        )
        final_answer_retry_limit = int(
            OmegaConf.select(
                self.config,
                "qa_manager.final_answer_retry_limit",
                default=FINAL_ANSWER_RETRY_LIMIT,
            )
        )

        def run_inference(input_dict, agent_name):
            return self.async_inference(input_dict, agent_name=agent_name)

        if retrieval_topk < 1:
            raise ValueError(f"qa_manager.retrieval_topk must be positive, got {retrieval_topk}")
        if max_nodes_per_turn < 0:
            raise ValueError(
                "qa_manager.max_nodes_per_turn must be non-negative "
                f"(0 disables the limit), got {max_nodes_per_turn}"
            )
        if search_rewrite_max_retries < 0 or final_answer_retry_limit < 0:
            raise ValueError("rollout retry limits must be non-negative")
        if not 0.0 <= invalid_workflow_reward_cap <= 1.0:
            raise ValueError("qa_manager.invalid_workflow_reward_cap must be in [0, 1]")

        if isinstance(question, str) and not question.endswith('?'):
            question += '?'

        def align_item_to_target_format(item_dict, target_dict):
            """
            灏?item_dict 瀵归綈鍒?target_dict 鐨勬牸寮忥細
            - 淇濊瘉鍖呭惈 target_dict 鐨勬墍鏈?key
            - 绫诲瀷涓?target_dict 瀵瑰簲鐨勫€间繚鎸佷竴鑷?            - 鎸?target 缁村害鍔?batch 缁达紝浣嗕笉鎴柇鏁版嵁
            """
            new_item_dict = {}

            for key, target_val in target_dict.items():
                # 娌℃湁璇?key锛岀洿鎺ュ鍒?target
                if key not in item_dict:
                    val = copy.deepcopy(target_val)
                else:
                    val = item_dict[key]

                    # Torch Tensor
                    if isinstance(target_val, torch.Tensor):
                        if not isinstance(val, torch.Tensor):
                            val = torch.as_tensor(val, dtype=target_val.dtype)
                        if val.ndim < target_val.ndim:
                            val = val.unsqueeze(0)

                    # NumPy 鏁扮粍
                    elif isinstance(target_val, np.ndarray):
                        if not isinstance(val, np.ndarray):
                            val = np.array(val, dtype=target_val.dtype)
                        # 濡傛灉 target 鏄?shape=(1,), dtype=object锛宨tem涔熷簲璇ュ寘涓€灞傛壒
                        if target_val.ndim > val.ndim:
                            val = np.expand_dims(val, axis=0)

                        if target_val.dtype == object:
                            # target: array([list([...])], dtype=object)
                            # item: array([...], dtype=object)
                            if (target_val.shape[0] == 1 and
                                isinstance(target_val[0], list) and
                                not isinstance(val[0], list)):
                                # 鍖呮垚 list
                                val = np.array([list(val)], dtype=object)

                    # list
                    elif isinstance(target_val, list):
                        if not isinstance(val, list):
                            val = [val]
                        # target 鏄?batch list: [list([...])]
                        if isinstance(target_val[0], list) and not isinstance(val[0], list):
                            val = [val]

                    # 鍏朵粬绫诲瀷锛屾寜 target 绫诲瀷鍖呰 batch
                    else:
                        if isinstance(target_val, np.ndarray) and target_val.ndim > 0:
                            if not isinstance(val, np.ndarray):
                                val = np.array([val], dtype=target_val.dtype)
                        elif isinstance(target_val, list):
                            val = [val]

                new_item_dict[key] = val

            return new_item_dict

        # dataproto鍒楄〃 [dataproto, penalty, reward(final_f1), whole(final_reward), role]
        single_batch_list = []

        def append_step(data, penalty, reward_value, whole_value, agent_name, node_id="", node_type=""):
            row_count = data.batch.batch_size[0]
            data.non_tensor_batch["node_id"] = np.full(row_count, str(node_id), dtype=object)
            data.non_tensor_batch["node_type"] = np.full(row_count, str(node_type), dtype=object)
            single_batch_list.append([data, penalty, reward_value, whole_value, agent_name])

        record_metrics = {}
        for metric in ['reward', 'penalty', 'whole']:
            record_metrics[metric] = {}
            for agent_name in ['PlanningAgent', 'QueryRewriteAgent', 'ReasonerAgent', 'AnswerSummarizationAgent', 'AnswerGenerationAgent']:
                record_metrics[metric][agent_name] = []
        record_metrics['times'] = {}
        for agent_name in ['PlanningAgent', 'QueryRewriteAgent', 'ReasonerAgent', 'AnswerSummarizationAgent', 'AnswerGenerationAgent']:
            record_metrics['times'][agent_name] = 0
        record_metrics.update(
            {
                'planned_search_nodes': 0,
                'planned_reason_nodes': 0,
                'summary_attempted': 0,
                'summary_first_valid': 0.0,
                'summary_retry_used': 0.0,
                'workflow_valid': 0.0,
                # Subgoal Plan v1 only (stay 0 for typed plans)
                'subgoal_steps': 0,
                'subgoal_memory_steps': 0,
                'subgoal_search_steps': 0,
                'summary_fallback': 0.0,
            }
        )

        def finalize_early_return(final_f1=0.0):
            record_metrics['final_f1'] = final_f1
            record_metrics['final_reward'] = final_f1
            record_metrics['final_em'] = 0.0
            record_metrics['final_answer_f1'] = 0.0
            record_metrics['final_answer'] = ""
            for step_index, (data, penalty, reward_value, whole_value, agent_name) in enumerate(single_batch_list):
                data.batch['reward_tensor'] = self.assign_rewards(data, whole_value)
                row_count = data.batch.batch_size[0]
                data.non_tensor_batch['role'] = np.full(row_count, agent_name, dtype=object)
                data.non_tensor_batch['workflow_step'] = np.full(row_count, step_index, dtype=np.int64)
                data.non_tensor_batch['workflow_tool_steps'] = np.full(
                    row_count, int(record_metrics.get('retrieval_times', 0)), dtype=np.int64
                )
                data.non_tensor_batch['outcome_reward'] = np.full(row_count, final_f1, dtype=np.float32)
                data.non_tensor_batch['outcome_exact'] = np.zeros(row_count, dtype=np.float32)
                data.non_tensor_batch['outcome_grounded'] = np.zeros(row_count, dtype=np.bool_)
                data.non_tensor_batch['workflow_valid'] = np.zeros(row_count, dtype=np.bool_)
                # Must be present on every row regardless of path, like the fields above: DataProto.concat requires
                # identical non_tensor_batch keys across all workflows in a batch. "usable=False" here is correct,
                # not a placeholder: this early-return path never ran the retrieval check this flag reports on.
                data.non_tensor_batch['nrpsc_tiebreak_usable'] = np.zeros(row_count, dtype=np.bool_)
                data.non_tensor_batch['nrpsc_tiebreak_hit'] = np.zeros(row_count, dtype=np.bool_)
                data.non_tensor_batch['nrpsc_tiebreak_f1_decile'] = np.zeros(row_count, dtype=np.int64)
                record_metrics['reward'][agent_name].append(reward_value)
                record_metrics['penalty'][agent_name].append(penalty)
                record_metrics['whole'][agent_name].append(whole_value)
            return [item[0] for item in single_batch_list], record_metrics

        if show_process:
            print("=== question===\n{}".format(question))
            print("=== answer===\n{}".format(answer))
            print("\n\n")

        # 璁板綍retrieval times
        record_metrics['retrieval_times'] = 0

        raw_data_source = target_dict.get("data_source", "unknown")
        if isinstance(raw_data_source, torch.Tensor):
            raw_data_source = raw_data_source.flatten()[0].item() if raw_data_source.numel() else "unknown"
        elif isinstance(raw_data_source, (list, tuple, np.ndarray)):
            raw_data_source = raw_data_source[0] if len(raw_data_source) else "unknown"
        data_source = str(raw_data_source or "unknown")
        normalized_data_source = data_source.strip().casefold().replace("-", "").replace("_", "")
        if normalized_data_source in {"2wiki", "2wikimultihopqa"}:
            normalized_data_source = "2wiki"
        record_metrics["data_source"] = normalized_data_source or "unknown"
        # ==================== Phase 1: Unified PlanningAgent ====================
        planning_agent_dict = qa_manager.trans_rawprompt_to_ids(
            "PlanningAgent",
            question,
        )
        planning_agent_dict_ = align_item_to_target_format(planning_agent_dict, target_dict)
        planning_data_ij = run_inference(planning_agent_dict_, 'PlanningAgent')
        planning_text = qa_manager.get_answers_text(planning_data_ij)[0]

        # 瑙ｆ瀽 planning 缁撴灉
        planning_output = qa_manager.parse_response(
            "PlanningAgent",
            planning_text,
            max_nodes=max_nodes_per_turn,
            question=question,
        )
        planning_is_valid = planning_output["is_valid"]
        append_step(planning_data_ij, 0.0, 0.0, 0.0, 'PlanningAgent', node_id="planning", node_type="planning")
        record_metrics['times']['PlanningAgent'] = 1
        record_metrics["planner_text"] = planning_text
        record_metrics["planner_valid"] = float(planning_is_valid)

        if show_process or (print_invalid_rollouts and not planning_is_valid):
            planning_prompt = planning_agent_dict.get("raw_prompt", [])
            planning_prompt_str = ""
            if planning_prompt:
                for msg in planning_prompt:
                    role = msg.get("role", "unknown")
                    content = msg.get("content", "")
                    planning_prompt_str += f"**{role.upper()}**:\n{content}\n\n"
            print(f"=== PlanningAgent input ===\n{planning_prompt_str}")
            print(f"=== PlanningAgent 杈撳嚭 ===\n{planning_text}")
            print(f"=== planning_is_valid ===\n{planning_is_valid}")
            if not planning_is_valid:
                print(f"=== error ===\n{planning_output.get('error', 'Unknown error')}")
                print(f"=== reason ===\n{planning_output.get('reason', 'Unknown reason')}")
            print()

        # Invalid planning is penalized directly; there is no fallback path in training.
        if not planning_is_valid:
            if show_process:
                print("=== workflow 鏃犳晥锛岃烦杩?DAG 鎵ц锛岀洿鎺ヨ绠楁牸寮忔儵缃?===\n\n")

            record_metrics['turn_number'] = 1

            # 鐩存帴杩斿洖锛岃烦杩?DAG 鎵ц
            return finalize_early_return()

        # ==================== ROSA DAG 鎵ц娴佺▼ ====================
        # 鏍规嵁 plan 涓殑 nodes 鎸夐『搴忔墽琛?        # nodes 鏍煎紡: [{"id": "1", "type": "search", "query": "..."}, {"id": "2", "type": "reason", "task": "..."}, ...]

        # 纭繚 nodes 鏄垪琛ㄧ被鍨嬶紙浠?planning_output 涓彁鍙栵級
        raw_nodes = planning_output.get("nodes", [])
        if isinstance(raw_nodes, list):
            nodes_list = [n for n in raw_nodes if isinstance(n, dict)]
        else:
            nodes_list = []
        record_metrics['planned_search_nodes'] = sum(
            str(node.get("type", "")).lower() == "search" for node in nodes_list
        )
        record_metrics['planned_reason_nodes'] = sum(
            str(node.get("type", "")).lower() == "reason" for node in nodes_list
        )
        record_metrics['subgoal_steps'] = sum(
            str(node.get("type", "")).lower() == "step" for node in nodes_list
        )
        context = {
            "original_query": question,
            "nodes": nodes_list,
            "resolved_subqs": [],
            "conclusions": [],
            "intermediate_results": {},  # 瀛樺偍涓棿缁撴灉锛宬ey 涓?node id
            "step_results": {},          # 瀛樺偍鑺傜偣缁撹锛屽榻?rosa_server_v2.py
            "phase2_messages": [{"role": "system", "content": qa_manager.Prompts["AnswerGenerationAgent"]}],
            "history_summary": "",
            "has_invalid_action": False,
        }

        record_metrics['turn_number'] = 1 + len(context["nodes"])

        def execute_search(node_id, raw_query, label):
            """Search node body, shared by typed <search> nodes and subgoal steps routed to retrieval:
            QueryRewrite (only when the text has #ID# dependencies) -> retrieval -> AnswerGeneration, one rewrite retry."""
            # Step 1: substitute #ID# with earlier answers
            resolved_query = raw_query
            for v_id in re.findall(r'#(\d+)#', raw_query):
                if v_id in context["step_results"]:
                    prev_ans = str(context["step_results"][v_id])
                    resolved_query = resolved_query.replace(f"#{v_id}#", prev_ans)

            has_dependencies = bool(re.findall(r'#(\d+)#', raw_query))

            if has_dependencies:
                qr_agent_dict = qa_manager.trans_rawprompt_to_ids(
                    "QueryRewriteAgent",
                    question,          # original_goal
                    raw_query,          # draft query with #ID#
                    context["step_results"]
                )
                qr_agent_dict_ = align_item_to_target_format(qr_agent_dict, target_dict)
                qr_data_ij = run_inference(qr_agent_dict_, 'QueryRewriteAgent')
                qr_text = qa_manager.get_answers_text(qr_data_ij)[0]
                qr_output = qa_manager.parse_response("QueryRewriteAgent", qr_text)
                rewritten_query = qr_output.get("query_rewrited", resolved_query)
                append_step(qr_data_ij, 0.0, 0.0, 0.0, 'QueryRewriteAgent', node_id=node_id, node_type="query_rewrite")
                record_metrics['times']['QueryRewriteAgent'] += 1

                if show_process:
                    qr_prompt = qr_agent_dict.get("raw_prompt", [])
                    qr_prompt_str = format_prompt_for_printing(qr_prompt)
                    print(f"=== QueryRewriteAgent [node {node_id}] input ===\n{qr_prompt_str}")
                    print(f"=== QueryRewriteAgent [node {node_id}] output ===\n{qr_text}")
                    print(f"=== has_dependencies: {has_dependencies}, raw_query: {raw_query}")
                    print(f"=== resolved_query: {resolved_query}")
                    print(f"=== rewritten_query: {rewritten_query}\n\n")
            else:
                rewritten_query = resolved_query
                if show_process:
                    print(f"=== Node {node_id} (no dependencies) ===")
                    print(f"=== rewritten_query: {rewritten_query}\n\n")

            # 2. Retrieval + evidence extraction, aligned with the compact RoSA server.
            current_query = rewritten_query
            attempted_queries = []
            rewrite_queries = []
            rewrite_used = False
            docs = []
            conclusion = ""

            for retry in range(search_rewrite_max_retries + 1):
                attempted_queries.append(current_query)
                docs = qa_manager.retrieval(current_query, top_k=retrieval_topk)
                record_metrics['retrieval_times'] += 1

                sq_user_content = build_search_user_content(current_query, docs)
                ag_messages = compact_phase2_messages(context["phase2_messages"]) + [
                    {"role": "user", "content": sq_user_content}
                ]
                try:
                    ag_agent_dict = qa_manager.trans_messages_to_ids(ag_messages)
                except NotImplementedError as exc:
                    if not is_prompt_too_long_error(exc):
                        raise
                    sq_user_content = build_search_user_content(
                        current_query,
                        truncate_docs_for_prompt(docs)
                    )
                    ag_messages = compact_phase2_messages(context["phase2_messages"]) + [
                        {"role": "user", "content": sq_user_content}
                    ]
                    try:
                        ag_agent_dict = qa_manager.trans_messages_to_ids(ag_messages)
                    except NotImplementedError as trim_exc:
                        if not is_prompt_too_long_error(trim_exc):
                            raise
                        sq_user_content = build_search_user_content(
                            current_query,
                            truncate_docs_for_prompt(docs, max_chars=600)
                        )
                        ag_messages = compact_phase2_messages(context["phase2_messages"]) + [
                            {"role": "user", "content": sq_user_content}
                        ]
                        ag_agent_dict = qa_manager.trans_messages_to_ids(ag_messages)
                    if show_process:
                        print(f"=== AnswerGenerationAgent prompt too long; using truncated current docs [node {node_id}] ===")
                ag_agent_dict_ = align_item_to_target_format(ag_agent_dict, target_dict)
                ag_data_ij = run_inference(ag_agent_dict_, 'AnswerGenerationAgent')
                ag_text = qa_manager.get_answers_text(ag_data_ij)[0]
                ag_output = qa_manager.parse_response("AnswerGenerationAgent", ag_text)

                context["phase2_messages"].append({"role": "user", "content": sq_user_content})
                context["phase2_messages"].append({"role": "assistant", "content": ag_text})

                is_valid = ag_output["is_valid"]
                if not is_valid:
                    context["has_invalid_action"] = True
                conclusion_candidate = ag_output.get("conclusion", "")
                rewrite_query = ag_output.get("rewrite", "")
                append_step(ag_data_ij, 0.0, 0.0, 0.0, 'AnswerGenerationAgent', node_id=node_id, node_type="search_answer")
                record_metrics['times']['AnswerGenerationAgent'] += 1

                if show_process:
                    ag_prompt = ag_agent_dict.get("raw_prompt", [])
                    ag_prompt_str = format_prompt_for_printing(ag_prompt)
                    print(f"=== AnswerGenerationAgent [node {node_id}] input ===\n{ag_prompt_str}")
                    print(f"=== AnswerGenerationAgent [node {node_id}] output ===\n{ag_text}")

                if is_valid and ag_output.get("has_conclusion", False):
                    conclusion = conclusion_candidate
                    break

                if is_valid and rewrite_query and not rewrite_used and retry < search_rewrite_max_retries:
                    rewritten_line = rewrite_query.strip().split("\n")[0].strip()
                    if (
                        rewritten_line
                        and len(rewritten_line) > 3
                        and rewritten_line.lower() != current_query.lower()
                        and rewritten_line not in attempted_queries
                    ):
                        rewrite_queries.append(rewritten_line)
                        current_query = rewritten_line
                        rewrite_used = True
                        if show_process:
                            print(f"=== Search context insufficient; rewrite once [node {node_id}] ===")
                            print(f"=== failed_query: {attempted_queries[-1]}")
                            print(f"=== rewritten: {rewritten_line}\n")
                        continue

                conclusion = "Insufficient information"
                break

            context["intermediate_results"][node_id] = {
                "query": rewritten_query,
                "executed_query": current_query,
                "attempted_queries": attempted_queries,
                "rewrite_queries": rewrite_queries,
                "docs": docs,
                "conclusion": conclusion
            }
            context["resolved_subqs"].append(current_query)
            context["conclusions"].append(conclusion)
            context["step_results"][node_id] = conclusion
            context["history_summary"] += f"Task {node_id} [{label}]: {raw_query.strip()}\nConclusion: {conclusion}\n\n"

            if show_process:
                print(f"=== conclusion: {conclusion}")
                print(f"=== step_results updated: {context['step_results']}\n\n")
            return conclusion

        step_texts = {str(plan_node.get("id", "")): str(plan_node.get("task", plan_node.get("query", "")))
                      for plan_node in context["nodes"]}

        # 閬嶅巻鎵€鏈夎妭鐐癸紝鎸?plan 椤哄簭鎵ц
        for node in context["nodes"]:
            node_id = node.get("id", "")
            node_type = node.get("type")

            if node_type == "search":
                execute_search(node_id, node.get("query", ""), "SEARCH")

            elif node_type == "step":
                # Subgoal Plan v1: the Planner only states the sub-question; the executor picks how to answer it.
                # A step without #ID# dependencies has no earlier answers to use, so it is always retrieved. A dependent
                # step is first offered to the ReasonerAgent with the referenced answers; it either answers from them
                # or asks for retrieval (also the fallback for malformed or "insufficient" outputs).
                step_text = str(node.get("task", ""))
                refs = list(dict.fromkeys(re.findall(r'#(\d+)#', step_text)))
                answered_from_memory = False
                if refs:
                    resolved_step = step_text
                    for v_id in refs:
                        if v_id in context["step_results"]:
                            resolved_step = resolved_step.replace(f"#{v_id}#", str(context["step_results"][v_id]))
                    known_facts = [
                        (v_id, step_texts.get(v_id, ""), str(context["step_results"].get(v_id, "")))
                        for v_id in refs
                    ]
                    route_messages = build_subgoal_route_messages(resolved_step, known_facts)
                    route_agent_dict = qa_manager.trans_messages_to_ids(route_messages)
                    route_agent_dict_ = align_item_to_target_format(route_agent_dict, target_dict)
                    route_data_ij = run_inference(route_agent_dict_, 'ReasonerAgent')
                    route_text = qa_manager.get_answers_text(route_data_ij)[0]
                    route = parse_subgoal_route(route_text)
                    if not route["is_valid"]:
                        context["has_invalid_action"] = True
                    append_step(route_data_ij, 0.0, 0.0, 0.0, 'ReasonerAgent', node_id=node_id, node_type="route")
                    record_metrics['times']['ReasonerAgent'] += 1
                    if show_process:
                        print(f"=== Route [step {node_id}] input ===\n{format_prompt_for_printing(route_messages)}")
                        print(f"=== Route [step {node_id}] output ===\n{route_text}\n=== route: {route['route']}\n")
                    if route["route"] == "memory":
                        answered_from_memory = True
                        conclusion = route["conclusion"]
                        context["intermediate_results"][node_id] = {
                            "task": step_text,
                            "resolved_task": resolved_step,
                            "conclusion": conclusion,
                            "route": "memory",
                        }
                        context["conclusions"].append(conclusion)
                        context["step_results"][node_id] = conclusion
                        context["history_summary"] += f"Task {node_id} [STEP]: {step_text.strip()}\nConclusion: {conclusion}\n\n"
                        record_metrics['subgoal_memory_steps'] += 1
                if not answered_from_memory:
                    execute_search(node_id, step_text, "STEP")
                    record_metrics['subgoal_search_steps'] += 1

            elif node_type == "reason":
                # ========== 鎵ц reason 鑺傜偣 ==========
                raw_task = node.get("task", "")

                # Step 1: 鍙橀噺鏇挎崲锛堝榻?rosa_server_v2.py 绗?362-370 琛岋級
                resolved_task = raw_task
                for v_id in re.findall(r'#(\d+)#', raw_task):
                    if v_id in context["step_results"]:
                        prev_ans = str(context["step_results"][v_id])
                        resolved_task = resolved_task.replace(f"#{v_id}#", prev_ans)

                reason_agent_dict = qa_manager.trans_rawprompt_to_ids("ReasonerAgent", resolved_task)
                reason_agent_dict_ = align_item_to_target_format(reason_agent_dict, target_dict)
                reason_data_ij = run_inference(reason_agent_dict_, 'ReasonerAgent')
                reason_text = qa_manager.get_answers_text(reason_data_ij)[0]
                reason_output = qa_manager.parse_response("ReasonerAgent", reason_text)
                reason_conclusion = reason_output.get("conclusion", "")
                is_valid = reason_output["is_valid"]
                if not is_valid:
                    context["has_invalid_action"] = True
                append_step(reason_data_ij, 0.0, 0.0, 0.0, 'ReasonerAgent', node_id=node_id, node_type="reason")
                record_metrics['times']['ReasonerAgent'] += 1

                # 瀛樺偍涓棿缁撴灉
                context["intermediate_results"][node_id] = {
                    "task": raw_task,
                    "resolved_task": resolved_task,
                    "conclusion": reason_conclusion
                }
                context["conclusions"].append(reason_conclusion)
                context["history_summary"] += f"Task {node_id} [REASON]: {raw_task.strip()}\nConclusion: {reason_conclusion}\n\n"
                context["step_results"][node_id] = reason_conclusion  # 瀵归綈 rosa_server_v2.py

                if show_process:
                    # 鎵撳嵃 ReasonerAgent 鐨勮緭鍏?prompt
                    reason_prompt = reason_agent_dict.get("raw_prompt", [])
                    reason_prompt_str = format_prompt_for_printing(reason_prompt)
                    print(f"=== ReasonerAgent [node {node_id}] 杈撳叆 ===\n{reason_prompt_str}")
                    print(f"=== ReasonerAgent [node {node_id}] 杈撳嚭 ===\n{reason_text}")
                    print(f"=== raw_task: {raw_task}")
                    print(f"=== resolved_task: {resolved_task}")
                    print(f"=== reason_conclusion: {reason_conclusion}")
                    print(f"=== step_results updated: {context['step_results']}\n\n")

        # ========== AnswerSummarizationAgent (濮嬬粓鎵ц) ==========
        full_history_messages = [
            {"role": "system", "content": qa_manager.Prompts["AnswerSummarizationAgent"]},
            {
                "role": "user",
                "content": (
                    f"**Original Question**: {question}\n\n"
                    f"**Resolved Sub-questions**:\n{context['history_summary'].strip()}"
                )
            },
        ]
        final_messages = full_history_messages
        if record_metrics['subgoal_steps']:
            # Subgoal Plan v1: the last step answers the original question, so the summarizer only normalizes that
            # answer. When the last step failed it falls back to the full step history (the typed-plan summarizer
            # prompt), and that fallback is recorded separately.
            final_step = context["nodes"][-1]
            final_step_answer = str(context["step_results"].get(str(final_step.get("id", "")), ""))
            if final_step_answer and not is_invalid_conclusion(final_step_answer):
                final_messages = build_subgoal_final_messages(question, str(final_step.get("task", "")), final_step_answer)
            else:
                final_messages = [{"role": "system", "content": FINAL_SYSTEM_MSG}, full_history_messages[1]]
                record_metrics['summary_fallback'] = 1.0
        as_agent_dict = qa_manager.trans_messages_to_ids(final_messages)
        as_agent_dict_ = align_item_to_target_format(as_agent_dict, target_dict)
        as_data_ij = run_inference(as_agent_dict_, 'AnswerSummarizationAgent')
        as_text = qa_manager.get_answers_text(as_data_ij)[0]
        as_output = qa_manager.parse_response("AnswerSummarizationAgent", as_text)
        is_valid = as_output["is_valid"]
        record_metrics['summary_attempted'] = 1
        record_metrics['summary_first_valid'] = float(is_valid)
        if not is_valid:
            context["has_invalid_action"] = True
        final_ans = as_output.get("answer", "") if is_valid else ""
        append_step(as_data_ij, 0.0, 0.0, 0.0, 'AnswerSummarizationAgent', node_id="summary", node_type="summary")
        record_metrics['times']['AnswerSummarizationAgent'] += 1

        if not final_ans and final_answer_retry_limit > 0:
            record_metrics['summary_retry_used'] = 1.0
            retry_messages = list(final_messages) + [
                {"role": "assistant", "content": as_text},
                {"role": "user", "content": "Output the supported short answer inside the required <answer> XML tag."},
            ]
            retry_agent_dict = qa_manager.trans_messages_to_ids(retry_messages)
            retry_agent_dict_ = align_item_to_target_format(retry_agent_dict, target_dict)
            retry_data_ij = run_inference(retry_agent_dict_, 'AnswerSummarizationAgent')
            retry_text = qa_manager.get_answers_text(retry_data_ij)[0]
            retry_output = qa_manager.parse_response("AnswerSummarizationAgent", retry_text)
            retry_is_valid = retry_output["is_valid"]
            if not retry_is_valid:
                context["has_invalid_action"] = True
            append_step(retry_data_ij, 0.0, 0.0, 0.0, 'AnswerSummarizationAgent', node_id="summary-retry", node_type="summary")
            record_metrics['times']['AnswerSummarizationAgent'] += 1
            final_ans = retry_output.get("answer", "") if retry_is_valid else "Execution Failed (missing <answer> tag)"

            if show_process:
                retry_prompt = retry_agent_dict.get("raw_prompt", [])
                retry_prompt_str = format_prompt_for_printing(retry_prompt)
                print(f"=== AnswerSummarizationAgent Retry 杈撳叆 ===\n{retry_prompt_str}")
                print(f"=== AnswerSummarizationAgent Retry 杈撳嚭 ===\n{retry_text}")

        if show_process:
            # 鎵撳嵃 AnswerSummarizationAgent 鐨勮緭鍏?prompt
            as_prompt = as_agent_dict.get("raw_prompt", [])
            as_prompt_str = format_prompt_for_printing(as_prompt)
            print(f"=== AnswerSummarizationAgent 杈撳叆 ===\n{as_prompt_str}")
            print(f"=== AnswerSummarizationAgent 杈撳嚭 ===\n{as_text}")
            print(f"=== final_answer ===\n{final_ans}\n\n")

        final_scores = compute_scores([final_ans], [flatten_answer_candidates(answer) or [""]])
        final_reward = compute_final_answer_reward(final_ans, answer, em_weight=final_reward_em_weight)
        final_is_grounded = is_supported_answer(final_ans, context["conclusions"])
        nrpsc_tiebreak_usable, nrpsc_tiebreak_hit = nrpsc_tiebreak_signal(
            question, answer, context["intermediate_results"]
        )
        workflow_is_rewardable = not context["has_invalid_action"] and (
            final_is_grounded or not require_grounded_final
        )
        record_metrics['workflow_valid'] = float(not context["has_invalid_action"])
        if not workflow_is_rewardable:
            final_reward = min(final_reward, invalid_workflow_reward_cap)
        action_trace = []
        for data, _, _, _, agent_name in single_batch_list:
            action_trace.append(
                {
                    "role": str(agent_name),
                    "node_id": str(data.non_tensor_batch.get("node_id", [""])[0]),
                    "response": str(qa_manager.get_answers_text(data)[0]),
                    "temperature": data.non_tensor_batch.get(
                        "effective_sampling_temperature", [None]
                    )[0],
                }
            )
        record_metrics["action_trace"] = action_trace
        for item in single_batch_list:
            item[2] = final_reward
            item[3] = final_reward

        # record metrics
        # [dataproto, penalty, final_f1, final_reward, agent_name]
        for step_index, item in enumerate(single_batch_list):
            agent_name = item[4]
            row_count = item[0].batch.batch_size[0]
            item[0].non_tensor_batch['role'] = np.full(row_count, agent_name, dtype=object)
            item[0].non_tensor_batch['workflow_step'] = np.full(row_count, step_index, dtype=np.int64)
            item[0].non_tensor_batch['workflow_tool_steps'] = np.full(
                row_count, int(record_metrics.get('retrieval_times', 0)), dtype=np.int64
            )
            item[0].non_tensor_batch['outcome_reward'] = np.full(row_count, final_reward, dtype=np.float32)
            item[0].non_tensor_batch['outcome_exact'] = np.full(row_count, final_scores['em'], dtype=np.float32)
            item[0].non_tensor_batch['outcome_grounded'] = np.full(row_count, final_is_grounded, dtype=np.bool_)
            item[0].non_tensor_batch['workflow_valid'] = np.full(
                row_count, not context["has_invalid_action"], dtype=np.bool_
            )
            item[0].non_tensor_batch['nrpsc_tiebreak_usable'] = np.full(
                row_count, nrpsc_tiebreak_usable, dtype=np.bool_
            )
            item[0].non_tensor_batch['nrpsc_tiebreak_hit'] = np.full(
                row_count, nrpsc_tiebreak_hit, dtype=np.bool_
            )
            item[0].non_tensor_batch['nrpsc_tiebreak_f1_decile'] = np.full(
                row_count, int(round(float(final_scores['f1']) * 10)), dtype=np.int64
            )
            record_metrics['reward'][agent_name].append(item[2])
            record_metrics['penalty'][agent_name].append(item[1])
            record_metrics['whole'][agent_name].append(item[3])
            record_metrics['final_f1'] = final_scores['f1']
            record_metrics['final_reward'] = final_reward
            record_metrics['final_em'] = final_scores['em']
            record_metrics['final_answer_f1'] = final_scores['f1']
            record_metrics['final_answer'] = final_ans

        # assign reward (reward_tensor)
        for item in single_batch_list:
            ## 璁＄畻reward_tensor

            # # 鏃爐urn number / retrieval times鐨刾enalty
            # cur_reward_tensor = self.assign_rewards(item[0], item[3])  # def assign_rewards(self, data, reward_value):

            # 鏈塼urn number / retrieval times鐨刾enalty
            cur_reward_tensor = self.assign_rewards(item[0], item[3])
            item[0].batch['reward_tensor'] = cur_reward_tensor

        # # ================= 浼樺寲鍏ㄩ儴妯″潡 =================
        single_batch_list = [item[0] for item in single_batch_list]

        # 杩斿洖鍐呭涓猴細dataproto list, metric dict
        return single_batch_list, record_metrics

    def async_inference(
        self,
        input_dict,
        agent_name='DefaultAgent',
        sampling_seed=None,
        sampling_temperature=None,
    ):
        """
        input_dict - 褰撳墠绗琲鏉ollout鐨勭j娆nput鐨刣ict
        """

        # 姝ゅ鐨刡atch瀹為檯涓?i,j)
        if sampling_temperature is None and getattr(self, "_val_greedy", False):
            # Validation uses deterministic decoding (temperature 0, top_p 1), per the evaluation contract.
            sampling_temperature = 0.0
        batch: DataProto = DataProto.from_single_dict(input_dict)
        if sampling_seed is not None:
            batch.non_tensor_batch["sampling_seed"] = np.full(
                len(batch.batch), int(sampling_seed), dtype=np.int64
            )
        if sampling_temperature is not None:
            batch.non_tensor_batch["sampling_temperature"] = np.full(
                len(batch.batch), float(sampling_temperature), dtype=np.float32
            )
        # add uid to batch
        batch.non_tensor_batch["uid"] = np.array([str(uuid.uuid4()) for _ in range(len(batch.batch))], dtype=object)
        gen_batch = self._get_gen_batch(batch)

        # pass global_steps to trace
        gen_batch.meta_info["global_steps"] = self.global_steps
        gen_batch_output = gen_batch.repeat(repeat_times=self.config.actor_rollout_ref.rollout.n, interleave=True)

        # async璇锋眰绗琲鏉ollout涓殑绗琷娆nference
        gen_batch_output = self.async_rollout_manager.generate_sequences(gen_batch_output)

        # repeat to align with repeated responses in rollout
        batch = batch.repeat(repeat_times=self.config.actor_rollout_ref.rollout.n, interleave=True)
        batch = batch.union(gen_batch_output)

        if "response_mask" not in batch.batch.keys():
            batch.batch["response_mask"] = compute_response_mask(batch)
        # Balance the number of valid tokens across DP ranks.
        # NOTE: This usually changes the order of data in the `batch`,
        # which won't affect the advantage calculation (since it's based on uid),
        # but might affect the loss calculation (due to the change of mini-batching).
        # # TODO: Decouple the DP balancing and mini-batching.
        # if self.config.trainer.balance_batch:
        #     self._balance_batch(batch, metrics=metrics)

        # compute global_valid tokens
        batch.meta_info["global_token_num"] = torch.sum(batch.batch["attention_mask"], dim=-1).tolist()

        # 姝ゅreturn鐨勬槸(i,j)鍗曟潯鐨刡atch
        return batch

    def assign_rewards(self, data, reward_value):
        # token and retrieval cost
        reward_tensor = torch.zeros_like(data.batch['responses'], dtype=torch.float32)

        for i in range(data.batch.batch_size[0]):
            # get position
            data_item = data[i]  # DataProtoItem
            prompt_ids = data_item.batch['prompts']
            prompt_length = prompt_ids.shape[-1]
            valid_response_length = data_item.batch['attention_mask'][prompt_length:].sum()

            reward_tensor[i, valid_response_length - 1] = reward_value

        return reward_tensor

    def _get_gen_batch(self, batch: DataProto) -> DataProto:
        reward_model_keys = set({"data_source", "reward_model", "extra_info", "uid"}) & batch.non_tensor_batch.keys()

        # pop those keys for generation
        batch_keys_to_pop = ["input_ids", "attention_mask", "position_ids"]
        non_tensor_batch_keys_to_pop = set(batch.non_tensor_batch.keys()) - reward_model_keys
        gen_batch = batch.pop(
            batch_keys=batch_keys_to_pop,
            non_tensor_batch_keys=list(non_tensor_batch_keys_to_pop),
        )

        # For agent loop, we need reward model keys to compute score.
        if self.async_rollout_mode:
            gen_batch.non_tensor_batch.update(batch.non_tensor_batch)

        return gen_batch

    # Features removed in the 2026-11-13 slimming (originals: _backup_pre_slim/ and
    # /home/hejingyu/projects/_deprecated_SIPPO-npu-nrpsc-20261113/). Each one was off in every W/P/NR-PSC run;
    # turning one back on must fail loudly here rather than silently run the plain workflow.
    _SLIM_REMOVED_ON = (
        "qa_manager.node_reward.enabled",
        "qa_manager.contract_preserving_dag_v2",
        "qa_manager.final_reward_f1_tiebreak_enabled",
        "algorithm.dag_opsd.enabled",
        "algorithm.workflow_sod.enabled",
        "actor_rollout_ref.actor.online_opsd.enabled",
    )

    def _plan_format(self):
        plan_format = str(OmegaConf.select(self.config, "qa_manager.plan_format", default="typed") or "typed").strip().lower()
        if plan_format not in {"typed", "subgoal"}:
            raise ValueError(f"qa_manager.plan_format must be typed or subgoal, got {plan_format!r}")
        return plan_format

    def _check_slim_rollout_config(self):
        self._plan_format()
        for key in self._SLIM_REMOVED_ON:
            if get_config_bool(self.config, key, default=False):
                raise NotImplementedError(f"{key}=true was removed from this tree (see _backup_pre_slim)")
        if self._planner_ccw_mode() != "off":
            raise NotImplementedError("algorithm.planner_ccw was removed from this tree (see _backup_pre_slim)")
        mode = str(OmegaConf.select(self.config, "qa_manager.execution_mode", default="multi_agent_dag"))
        if mode.strip().casefold() != "multi_agent_dag":
            raise NotImplementedError(f"qa_manager.execution_mode={mode!r} was removed; only multi_agent_dag is kept")
        if not get_config_bool(self.config, "qa_manager.result_reward_only", default=False):
            raise NotImplementedError("legacy process rewards were removed; qa_manager.result_reward_only must be true")

    def _nrpsc_frozen_tfidf(self):
        path = str(OmegaConf.select(self.config, "algorithm.planner_outcome_contrast.nrpsc_idf_path", default=""))
        expected = str(OmegaConf.select(self.config, "algorithm.planner_outcome_contrast.nrpsc_idf_sha256", default=""))
        if not path or not expected:
            raise ValueError("NR-PSC requires a frozen IDF path and expected SHA-256")
        cached = getattr(self, "_nrpsc_idf_cache", None)
        if cached is None or cached[:2] != (path, expected):
            scorer, actual = load_frozen_tfidf(path)
            if actual != expected.lower():
                raise ValueError("NR-PSC frozen IDF SHA-256 mismatch")
            cached = (path, expected, scorer)
            self._nrpsc_idf_cache = cached
        return cached[2]

    def _apply_planner_outcome_contrast(
        self, batch: DataProto
    ) -> tuple[DataProto, dict[str, float]]:
        """Attach an online sibling-outcome Planner contrast gradient."""

        cfg = OmegaConf.select(
            self.config, "algorithm.planner_outcome_contrast", default={}
        ) or {}
        raw_mode = cfg.get("mode", "off")
        mode = "off" if raw_mode is False or raw_mode is None else str(raw_mode).lower()
        minibatch_mode = str(cfg.get("minibatch_mode", "workflow_single"))
        if minibatch_mode not in {
            "action_row_legacy",
            "workflow_single",
            "question_preserving",
        }:
            raise ValueError(
                "algorithm.planner_outcome_contrast.minibatch_mode must be "
                "action_row_legacy, workflow_single, or question_preserving"
            )
        if minibatch_mode == "action_row_legacy" and mode != "off":
            raise ValueError(
                "action_row_legacy is a pure-EM control; POC requires "
                "question_preserving minibatches"
            )
        if mode == "off" and minibatch_mode != "question_preserving":
            return batch, {}
        if mode not in {"real", "shuffled", "nrpsc"}:
            if mode != "off":
                raise ValueError(
                    "algorithm.planner_outcome_contrast.mode must be off, real, shuffled, or nrpsc"
                )
        if mode == "nrpsc" and minibatch_mode != "question_preserving":
            raise ValueError("NR-PSC requires question-preserving minibatches")
        gradient_audit = bool(cfg.get("gradient_audit", False))
        coverage_audit_only = bool(cfg.get("coverage_audit_only", False))
        current_policy_audit_only = bool(
            cfg.get("current_policy_audit_only", False)
        )
        objective_ablation_variants = list(
            cfg.get("objective_ablation_variants", []) or []
        )
        permutation_count = int(cfg.get("permutation_count", 0) or 0)
        permutation_artifact_path = str(cfg.get("permutation_artifact_path", "") or "")
        if permutation_count < 0:
            raise ValueError("Planner outcome contrast permutation_count must be non-negative")
        if permutation_count > 0 and not current_policy_audit_only:
            raise ValueError(
                "Planner outcome contrast permutation audit requires current_policy_audit_only=true"
            )
        if gradient_audit and mode != "real":
            raise ValueError(
                "Planner outcome contrast gradient_audit requires mode=real"
            )
        if minibatch_mode == "question_preserving":
            if gradient_audit:
                raise ValueError(
                    "question-preserving POC uses refreshed per-minibatch coefficients; "
                    "run its separate one-batch audit instead of gradient_audit"
                )
            if coverage_audit_only and mode != "real":
                raise ValueError(
                    "Planner outcome contrast coverage audit requires mode=real"
                )
            if current_policy_audit_only and (
                mode != "real" or not bool(cfg.get("paired_shuffled_audit", False))
            ):
                raise ValueError(
                    "Current-policy POC audit requires mode=real and paired_shuffled_audit=true"
                )
            required_tensor = {
                "response_mask",
                "old_log_probs",
                "advantages",
                "actor_dp_valid_rows",
            }
            required_metadata = {
                "uid",
                "trajectory_id",
                "role",
                "outcome_exact",
                "workflow_step",
            }
            missing_tensor = required_tensor - set(batch.batch.keys())
            missing_metadata = required_metadata - set(batch.non_tensor_batch.keys())
            if missing_tensor or missing_metadata:
                raise ValueError(
                    "question-preserving POC is missing required batch fields: "
                    f"tensor={sorted(missing_tensor)}, metadata={sorted(missing_metadata)}"
                )
            if int(self.config.actor_rollout_ref.actor.ppo_epochs) != 1:
                raise ValueError("question-preserving POC requires actor ppo_epochs=1")
            if str(self.config.actor_rollout_ref.actor.loss_agg_mode) != "token-mean":
                raise ValueError(
                    "question-preserving POC requires actor loss_agg_mode=token-mean"
                )
            policy_mode = str(
                self.config.actor_rollout_ref.actor.policy_loss.get(
                    "loss_mode", "vanilla"
                )
            )
            if policy_mode != "vanilla":
                raise ValueError(
                    "question-preserving POC currently requires vanilla PPO loss"
                )

            actor_world_size = int(self.config.trainer.n_gpus_per_node) * int(
                self.config.trainer.nnodes
            )
            sequence_parallel_size = int(
                OmegaConf.select(
                    self.config,
                    "actor_rollout_ref.actor.ulysses_sequence_parallel_size",
                    default=1,
                )
            )
            if sequence_parallel_size != 1:
                raise ValueError(
                    "question-preserving refreshed POC currently requires "
                    "ulysses_sequence_parallel_size=1"
                )
            data_parallel_size = compute_actor_data_parallel_size(
                actor_world_size, sequence_parallel_size
            )
            if (
                data_parallel_size > 1
                and not bool(self.config.actor_rollout_ref.actor.use_dynamic_bsz)
            ):
                raise ValueError(
                    "multi-GPU question-preserving POC requires use_dynamic_bsz=true "
                    "so every rank executes the same number of FSDP microbatches"
                )
            loss_weight = 0.0 if mode == "off" else float(cfg.get("loss_weight", 0.1))
            if mode != "off" and (
                loss_weight <= 0 or not np.isfinite(loss_weight)
            ):
                raise ValueError(
                    "Planner outcome contrast loss_weight must be finite and positive"
                )

            metrics = {
                "aux/planner_outcome_contrast/enabled": float(mode != "off"),
                "aux/planner_outcome_contrast/question_preserving_minibatches": 1.0,
                "aux/planner_outcome_contrast/refresh_per_minibatch": float(
                    mode != "off"
                ),
                "aux/planner_outcome_contrast/loss_weight": loss_weight,
                "aux/planner_outcome_contrast/coverage_audit_only": float(
                    coverage_audit_only
                ),
            }
            nrpsc_idf = None
            if mode == "nrpsc":
                if "workflow_sample" not in batch.non_tensor_batch:
                    raise ValueError("NR-PSC requires workflow_sample metadata")
                expected_siblings = int(cfg.get("nrpsc_expected_siblings", 0))
                configured_siblings = int(OmegaConf.select(self.config, "qa_manager.workflow_rollout_n", default=0))
                if expected_siblings != configured_siblings:
                    raise ValueError("NR-PSC expected siblings differs from rollout configuration")
                sibling_questions = validate_sibling_groups(
                    batch.non_tensor_batch["uid"], batch.non_tensor_batch["trajectory_id"],
                    batch.non_tensor_batch["workflow_sample"],
                    batch.batch["actor_dp_valid_rows"].detach().cpu().numpy(), expected_siblings,
                )
                views, alignment_counts = prepare_plan_views(
                    self.tokenizer, batch.batch["responses"], batch.batch["response_mask"],
                    batch.batch["prompts"], batch.batch["attention_mask"],
                    batch.non_tensor_batch["role"],
                )
                documents = [node.text for view in views if view is not None for node in view.nodes]
                if not documents:
                    raise ValueError("NR-PSC has no parseable Planner nodes in this batch")
                nrpsc_scorer = self._nrpsc_frozen_tfidf()
                nrpsc_idf = nrpsc_scorer.idf
                batch.non_tensor_batch["nrpsc_plan_view"] = views
                metrics.update({f"aux/nrpsc/{key}": float(value)
                                for key, value in alignment_counts.items()})
                metrics["aux/nrpsc/complete_sibling_questions"] = float(sibling_questions)
                tiebreak_usable = np.asarray(batch.non_tensor_batch.get(
                    "nrpsc_tiebreak_usable", np.zeros(len(views), dtype=np.bool_)))
                tiebreak_hit = np.asarray(batch.non_tensor_batch.get(
                    "nrpsc_tiebreak_hit", np.zeros(len(views), dtype=np.bool_)))
                metrics["aux/nrpsc/tiebreak_usable_rows"] = float((tiebreak_usable & (views != None)).sum())  # noqa: E711
            if mode not in {"off", "nrpsc"}:
                initial = build_planner_outcome_contrast_coefficients(
                    response_mask=batch.batch["response_mask"],
                    old_log_probs=batch.batch["old_log_probs"],
                    question_ids=batch.non_tensor_batch["uid"],
                    trajectory_ids=batch.non_tensor_batch["trajectory_id"],
                    roles=batch.non_tensor_batch["role"],
                    outcomes=batch.non_tensor_batch["outcome_exact"],
                    chosen_eligibility=(actual_reward_eligibility(batch.non_tensor_batch)
                                        if cfg.get("use_reward_eligibility", False)
                                        else batch.non_tensor_batch.get("psc_chosen_eligible")),
                    contract_validity=batch.non_tensor_batch.get("contract_valid"),
                    runtime_lineage_validity=batch.non_tensor_batch.get(
                        "runtime_lineage_valid"
                    ),
                    answer_sink_support=batch.non_tensor_batch.get(
                        "answer_sink_supported"
                    ),
                    workflow_steps=batch.non_tensor_batch["workflow_step"],
                    valid_rows=batch.batch["actor_dp_valid_rows"],
                    beta=float(cfg.get("beta", 1.0)),
                    question_weighting=str(cfg.get("question_weighting", "question")),
                    **({
                        "remove_shared_prefix": True,
                        "response_token_ids": batch.batch["responses"],
                        "prompt_token_ids": batch.batch["prompts"],
                        "prompt_attention_mask": batch.batch["attention_mask"][:, :batch.batch["prompts"].shape[-1]],
                    } if cfg.get("remove_shared_prefix", False) else {}),
                    data_parallel_size=1,
                    shuffled=mode == "shuffled",
                    shuffle_seed=int(cfg.get("shuffle_seed", 0)),
                )
                metrics.update(initial.metrics)
                if (
                    bool(cfg.get("require_signal", True))
                    and initial.metrics[
                        "aux/planner_outcome_contrast/pair_count"
                    ]
                    <= 0
                ):
                    diagnostic_names = (
                        "raw_planner_workflow_count",
                        "raw_question_count",
                        "raw_positive_workflow_count",
                        "raw_eligible_workflow_count",
                        "raw_eligible_positive_workflow_count",
                        "raw_mixed_question_count",
                        "contract_valid_workflow_count",
                        "positive_contract_valid_workflow_count",
                        "runtime_lineage_valid_workflow_count",
                        "positive_runtime_lineage_valid_workflow_count",
                        "answer_sink_supported_workflow_count",
                        "positive_answer_sink_supported_workflow_count",
                        "eligibility_component_mismatch_workflow_count",
                        "ineligible_positive_workflow_count",
                        "pair_count",
                    )
                    diagnostics = ", ".join(
                        f"{name}={initial.metrics.get('aux/planner_outcome_contrast/' + name, 'missing')}"
                        for name in diagnostic_names
                    )
                    raise ValueError(
                        "Planner outcome contrast found no eligible pair; " + diagnostics
                    )

            batch.meta_info.update(
                {
                    "planner_outcome_contrast_minibatch_mode": minibatch_mode,
                    "planner_outcome_contrast_mode": mode,
                    "planner_outcome_contrast_beta": float(cfg.get("beta", 1.0)),
                    "planner_outcome_contrast_question_weighting": str(
                        cfg.get("question_weighting", "question")
                    ),
                    "planner_outcome_contrast_use_reward_eligibility": bool(
                        cfg.get("use_reward_eligibility", False)
                    ),
                    "planner_outcome_contrast_remove_shared_prefix": bool(
                        cfg.get("remove_shared_prefix", False)
                    ),
                    "nrpsc_idf": nrpsc_idf,
                    "nrpsc_unknown_idf": nrpsc_scorer.unknown_idf if mode == "nrpsc" else None,
                    "nrpsc_similarity_threshold": float(cfg.get("nrpsc_similarity_threshold", 0.8)),
                    "nrpsc_reliability_table": dict(cfg.get("nrpsc_reliability_table", {}) or {}),
                    "nrpsc_tiebreak_weight": float(cfg.get("nrpsc_tiebreak_weight", 0.0)),
                    "nrpsc_tiebreak_source": str(cfg.get("nrpsc_tiebreak_source", "retrieval")),
                    "planner_outcome_contrast_loss_weight": loss_weight,
                    "planner_outcome_contrast_shuffle_seed": int(
                        cfg.get("shuffle_seed", 0)
                    ),
                    "planner_outcome_contrast_require_signal": bool(
                        cfg.get("require_signal", True)
                    ),
                    "planner_outcome_contrast_coverage_audit_only": coverage_audit_only,
                    "planner_outcome_contrast_current_policy_audit_only": current_policy_audit_only,
                    "planner_outcome_contrast_objective_ablation_variants": objective_ablation_variants,
                    "planner_outcome_contrast_permutation_count": permutation_count,
                    "planner_outcome_contrast_permutation_artifact_path": permutation_artifact_path,
                    "planner_outcome_contrast_paired_shuffled_audit": bool(
                        cfg.get("paired_shuffled_audit", False)
                    ),
                    "planner_outcome_contrast_data_parallel_size": data_parallel_size,
                }
            )
            return batch, metrics
        required_tensor = {
            "response_mask",
            "old_log_probs",
            "advantages",
            "workflow_loss_weights",
        }
        required_metadata = {
            "uid",
            "trajectory_id",
            "role",
            "outcome_exact",
            "workflow_step",
        }
        missing_tensor = required_tensor - set(batch.batch.keys())
        missing_metadata = required_metadata - set(batch.non_tensor_batch.keys())
        if missing_tensor or missing_metadata:
            raise ValueError(
                "Planner outcome contrast is missing required batch fields: "
                f"tensor={sorted(missing_tensor)}, metadata={sorted(missing_metadata)}"
            )
        if int(self.config.actor_rollout_ref.actor.ppo_epochs) != 1:
            raise ValueError("Planner outcome contrast requires actor ppo_epochs=1")
        policy_mode = str(
            self.config.actor_rollout_ref.actor.policy_loss.get(
                "loss_mode", "vanilla"
            )
        )
        if policy_mode != "vanilla":
            raise ValueError("Planner outcome contrast currently requires vanilla PPO loss")

        actor_world_size = int(self.config.trainer.n_gpus_per_node) * int(
            self.config.trainer.nnodes
        )
        sequence_parallel_size = int(
            OmegaConf.select(
                self.config,
                "actor_rollout_ref.actor.ulysses_sequence_parallel_size",
                default=1,
            )
        )
        data_parallel_size = compute_actor_data_parallel_size(
            actor_world_size, sequence_parallel_size
        )
        result = build_planner_outcome_contrast_coefficients(
            response_mask=batch.batch["response_mask"],
            old_log_probs=batch.batch["old_log_probs"],
            question_ids=batch.non_tensor_batch["uid"],
            trajectory_ids=batch.non_tensor_batch["trajectory_id"],
            roles=batch.non_tensor_batch["role"],
            outcomes=batch.non_tensor_batch["outcome_exact"],
            chosen_eligibility=batch.non_tensor_batch.get("psc_chosen_eligible"),
            contract_validity=batch.non_tensor_batch.get("contract_valid"),
            runtime_lineage_validity=batch.non_tensor_batch.get(
                "runtime_lineage_valid"
            ),
            answer_sink_support=batch.non_tensor_batch.get("answer_sink_supported"),
            workflow_steps=batch.non_tensor_batch["workflow_step"],
            beta=float(cfg.get("beta", 1.0)),
            data_parallel_size=data_parallel_size,
            shuffled=mode == "shuffled",
            shuffle_seed=int(cfg.get("shuffle_seed", 0)),
        )
        pair_count = result.metrics[
            "aux/planner_outcome_contrast/pair_count"
        ]
        if bool(cfg.get("require_signal", True)) and pair_count <= 0:
            raise ValueError(
                "Planner outcome contrast found no mixed-EM sibling question"
            )
        loss_weight = float(cfg.get("loss_weight", 0.1))
        if loss_weight <= 0 or not np.isfinite(loss_weight):
            raise ValueError("Planner outcome contrast loss_weight must be finite and positive")

        coefficients = result.coefficients.to(
            device=batch.batch["old_log_probs"].device,
            dtype=torch.float32,
        )
        batch.batch["planner_outcome_contrast_coefficients"] = coefficients
        batch.meta_info["planner_outcome_contrast_loss_weight"] = loss_weight
        batch.meta_info["planner_outcome_contrast_gradient_audit"] = gradient_audit

        shuffled_result = None
        if gradient_audit:
            shuffled_result = build_planner_outcome_contrast_coefficients(
                response_mask=batch.batch["response_mask"],
                old_log_probs=batch.batch["old_log_probs"],
                question_ids=batch.non_tensor_batch["uid"],
                trajectory_ids=batch.non_tensor_batch["trajectory_id"],
                roles=batch.non_tensor_batch["role"],
                outcomes=batch.non_tensor_batch["outcome_exact"],
                chosen_eligibility=batch.non_tensor_batch.get("psc_chosen_eligible"),
                contract_validity=batch.non_tensor_batch.get("contract_valid"),
                runtime_lineage_validity=batch.non_tensor_batch.get(
                    "runtime_lineage_valid"
                ),
                answer_sink_support=batch.non_tensor_batch.get(
                    "answer_sink_supported"
                ),
                workflow_steps=batch.non_tensor_batch["workflow_step"],
                beta=float(cfg.get("beta", 1.0)),
                data_parallel_size=data_parallel_size,
                shuffled=True,
                shuffle_seed=int(cfg.get("shuffle_seed", 0)),
            )
            shuffled_pair_count = shuffled_result.metrics[
                "aux/planner_outcome_contrast/pair_count"
            ]
            if bool(cfg.get("require_signal", True)) and shuffled_pair_count <= 0:
                raise ValueError(
                    "Planner outcome contrast shuffled audit found no mixed-EM sibling question"
                )
            batch.batch["planner_outcome_contrast_shuffled_coefficients"] = (
                shuffled_result.coefficients.to(
                    device=batch.batch["old_log_probs"].device,
                    dtype=torch.float32,
                )
            )

        roles = np.asarray(batch.non_tensor_batch["role"], dtype=object)
        planner_rows = torch.as_tensor(
            roles == "PlanningAgent",
            device=coefficients.device,
            dtype=torch.bool,
        ).unsqueeze(-1)
        em_direct_gradient = (
            -batch.batch["advantages"].float()
            * batch.batch["workflow_loss_weights"].float()
        )
        poc_direct_gradient = coefficients * loss_weight
        planner_em_gradient = em_direct_gradient * planner_rows
        em_norm = torch.linalg.vector_norm(em_direct_gradient)
        planner_em_norm = torch.linalg.vector_norm(planner_em_gradient)
        poc_norm = torch.linalg.vector_norm(poc_direct_gradient)
        denominator = planner_em_norm.clamp_min(1e-12)
        cosine_denominator = (planner_em_norm * poc_norm).clamp_min(1e-12)
        cosine = torch.sum(planner_em_gradient * poc_direct_gradient) / cosine_denominator

        metrics = dict(result.metrics)
        if shuffled_result is not None:
            prefix = "aux/planner_outcome_contrast/"
            for key, value in shuffled_result.metrics.items():
                suffix = key.removeprefix(prefix)
                metrics[f"{prefix}shuffled_{suffix}"] = value
        metrics.update(
            {
                "aux/planner_outcome_contrast/enabled": 1.0,
                "aux/planner_outcome_contrast/gradient_audit": float(
                    gradient_audit
                ),
                "aux/planner_outcome_contrast/loss_weight": loss_weight,
                "aux/planner_outcome_contrast/em_direct_gradient_norm": float(
                    em_norm.item()
                ),
                "aux/planner_outcome_contrast/planner_em_direct_gradient_norm": float(
                    planner_em_norm.item()
                ),
                "aux/planner_outcome_contrast/poc_direct_gradient_norm": float(
                    poc_norm.item()
                ),
                "aux/planner_outcome_contrast/poc_to_planner_em_direct_gradient_ratio": float(
                    (poc_norm / denominator).item()
                ),
                "aux/planner_outcome_contrast/poc_planner_em_direct_gradient_cosine": float(
                    cosine.item() if poc_norm.item() > 0 and planner_em_norm.item() > 0 else 0.0
                ),
            }
        )
        return batch, metrics


    def _planner_ccw_mode(self):
        mode = str(
            OmegaConf.select(
                self.config,
                "algorithm.planner_ccw.mode",
                default="off",
            )
        ).strip().lower()
        if mode not in {"off", "control", "weighted"}:
            raise ValueError(
                "algorithm.planner_ccw.mode must be off, control, or weighted"
            )
        return mode

    def test_validate(self):
        import asyncio
        from qa_manager.ROSA import ROSA_AgentManager
        import numpy as np

        print('Testing Begin.')
        start_time = time.time()     # 璁板綍寮€濮嬫椂闂?
        # Wake up rollout engine once before validation.
        if self.config.actor_rollout_ref.rollout.free_cache_engine:
            self.async_rollout_manager.wake_up()

        self._check_slim_rollout_config()
        qa_manager = ROSA_AgentManager(self.tokenizer, self.config)

        all_test_metrics = []
        self._val_greedy = True

        async def run_batch(test_batch_dict):
            return await self.async_test(
                test_batch_dict,
                qa_manager,
                self.config.data.val_batch_size
            )

        # count = 0
        # for test_batch_dict in self.val_dataloader:
        for test_batch_dict in tqdm(self.val_dataloader, desc="Validating"):
            # count+=1
            try:
                loop = asyncio.get_running_loop()
                _, test_reward_metrics = loop.run_until_complete(run_batch(test_batch_dict))
            except RuntimeError:
                # 娌℃湁杩愯浜嬩欢寰幆
                _, test_reward_metrics = asyncio.run(run_batch(test_batch_dict))

            all_test_metrics.append(test_reward_metrics)

            _val_dir = self.config.trainer.get("validation_data_dir", None)
            if _val_dir:
                try:
                    import json as _json
                    import os as _os
                    _os.makedirs(_val_dir, exist_ok=True)
                    _fn = _os.path.join(_val_dir, f"val_step{self.global_steps}.jsonl")
                    with open(_fn, "a", encoding="utf-8") as _f:
                        for _rec in getattr(self, "_val_batch_records", []):
                            _rec = dict(_rec)
                            _rec["batch_index"] = len(all_test_metrics) - 1
                            _f.write(_json.dumps(
                                _rec, ensure_ascii=False,
                                default=lambda o: o.tolist() if hasattr(o, "tolist") else str(o),
                            ) + "\n")
                except Exception as _e:
                    print(f"[val_jsonl] write failed: {_e}")

            # if count >= 3:
            #     break

        self._val_greedy = False

        # 鏀跺熬
        if self.config.actor_rollout_ref.rollout.free_cache_engine:
            self.async_rollout_manager.sleep()

        end_time = time.time()       # 璁板綍缁撴潫鏃堕棿
        elapsed_time = end_time - start_time  # 绉掍负鍗曚綅鐨勬椂闂村樊
        print(f"Testing elapsed time: {elapsed_time:.2f} seconds")

        # # 璁＄畻骞冲潎鍊?        # final_metrics = {}
        # for key in all_test_metrics[-1].keys():
        #     final_metrics[key] = np.mean([dic[key] for dic in all_test_metrics])

        # Compute averaged validation metrics.
        all_keys = set()
        for d in all_test_metrics:
            all_keys.update(d.keys())
        final_metrics = {}
        for key in all_keys:
            values = [d[key] for d in all_test_metrics if key in d]
            final_metrics[key] = np.mean(values)

        return final_metrics

    async def async_test(self, batch_dict, qa_manager, max_workers=4):
        """
        寮傛鎵归噺 rollout锛岄噰鐢?asyncio.as_completed 闃查暱灏俱€?        """
        import torch
        import numpy as np
        import asyncio
        import logging
        from tqdm import tqdm

        questions = [item['question'] for item in batch_dict['extra_info']]  # [:1000]
        answers = [item['answer'] for item in batch_dict['extra_info']]  # [:1000]
        raw_data_sources = batch_dict.get('data_source')
        if raw_data_sources is None:
            data_sources = ['unknown'] * len(questions)
        else:
            data_sources = [str(source) for source in raw_data_sources]
        batch: DataProto = DataProto.from_single_dict(batch_dict)

        def select_item_keep_dim(batch_dict, idx):
            item_dict = {}
            for key, value in batch_dict.items():
                if isinstance(value, torch.Tensor):
                    item_dict[key] = value[idx:idx+1]
                elif isinstance(value, np.ndarray):
                    item_dict[key] = value[idx:idx+1]
                elif isinstance(value, list):
                    item_dict[key] = [value[idx]]
                else:
                    try:
                        item_dict[key] = value[idx:idx+1]
                    except Exception:
                        item_dict[key] = value
            return item_dict

        # Metrics initialization.
        final_em_list, final_reward_list = [], []
        em_by_source, reward_by_source = defaultdict(list), defaultdict(list)
        turn_number_list, retrieval_times_list = [], []
        planned_search_nodes_list, planned_reason_nodes_list = [], []
        summary_first_valid_list, summary_retry_used_list = [], []
        workflow_valid_list = []
        subgoal_lists = {key: [] for key in SUBGOAL_METRIC_KEYS}
        record_metrics_batch = {
            'times': {
                agent: []
                for agent in ['PlanningAgent', 'QueryRewriteAgent', 'ReasonerAgent', 'AnswerSummarizationAgent', 'AnswerGenerationAgent']
            }
        }

        self._val_batch_records = []

        async def process_single_item(item_id, question, answer, data_source, semaphore):
            async with semaphore:
                item_dict = select_item_keep_dim(batch_dict, item_id)
                _, record_metrics = await asyncio.to_thread(
                    self.async_rollout_single, qa_manager, item_dict, question, answer, False
                )
                try:
                    self._val_batch_records.append({
                        "batch_item": int(item_id),
                        "data_source": data_source,
                        "question": question,
                        "gold_answers": answer,
                        "final_answer": record_metrics.get("final_answer"),
                        "final_em": record_metrics.get("final_em"),
                        "final_f1": record_metrics.get("final_f1"),
                        "final_reward": record_metrics.get("final_reward"),
                        "workflow_valid": record_metrics.get("workflow_valid"),
                        "turn_number": record_metrics.get("turn_number"),
                        "retrieval_times": record_metrics.get("retrieval_times"),
                        "planned_search_nodes": record_metrics.get("planned_search_nodes"),
                        "planned_reason_nodes": record_metrics.get("planned_reason_nodes"),
                        "planner_text": record_metrics.get("planner_text"),
                        "planner_valid": record_metrics.get("planner_valid"),
                        "action_trace": record_metrics.get("action_trace"),
                        "times": record_metrics.get("times"),
                        **{key: record_metrics.get(key) for key in SUBGOAL_METRIC_KEYS},
                    })
                except Exception:
                    pass
                # 鏀堕泦鏁版嵁
                final_em = record_metrics.get('final_em', 0.0)
                final_reward = record_metrics.get('final_reward', record_metrics['final_f1'])
                final_em_list.append(final_em)
                final_reward_list.append(final_reward)
                em_by_source[data_source].append(final_em)
                reward_by_source[data_source].append(final_reward)
                turn_number_list.append(record_metrics['turn_number'])
                retrieval_times_list.append(record_metrics['retrieval_times'])
                planned_search_nodes_list.append(record_metrics['planned_search_nodes'])
                planned_reason_nodes_list.append(record_metrics['planned_reason_nodes'])
                workflow_valid_list.append(record_metrics['workflow_valid'])
                if record_metrics['summary_attempted']:
                    summary_first_valid_list.append(record_metrics['summary_first_valid'])
                    summary_retry_used_list.append(record_metrics['summary_retry_used'])
                for key in subgoal_lists:
                    subgoal_lists[key].append(record_metrics.get(key, 0))
            for agent_name in ['PlanningAgent', 'QueryRewriteAgent', 'ReasonerAgent', 'AnswerSummarizationAgent', 'AnswerGenerationAgent']:
                record_metrics_batch['times'][agent_name].append(record_metrics['times'][agent_name])

        # 鍒涘缓浠诲姟
        semaphore = asyncio.Semaphore(max_workers)
        tasks = [
            asyncio.create_task(process_single_item(item_id, q, a, source, semaphore))
            for item_id, (q, a, source) in enumerate(zip(questions, answers, data_sources, strict=True))
        ]

        # 鎸夊畬鎴愰『搴忓鐞嗕换鍔★紝鍑忓皯闀垮熬绛夊緟
        # for fut in tqdm(asyncio.as_completed(tasks), total=len(tasks), desc="Async Rollout"):
        for fut in asyncio.as_completed(tasks):
            try:
                await fut
            except Exception as e:
                import traceback
                logging.error(f"Task failed: {e}")
                logging.error(f"Traceback: {traceback.format_exc()}")

        # # 璁＄畻鏈€缁?metrics
        test_reward_metrics = {
            "validation/workflow/turns_mean": np.mean(turn_number_list),
            "validation/workflow/retrieval_calls_mean": np.mean(retrieval_times_list),
            "validation/workflow/planned_search_nodes_mean": np.mean(planned_search_nodes_list),
            "validation/workflow/planned_reason_nodes_mean": np.mean(planned_reason_nodes_list),
            "validation/workflow/summary_first_valid_rate": (
                np.mean(summary_first_valid_list) if summary_first_valid_list else 0.0
            ),
            "validation/workflow/summary_retry_rate": (
                np.mean(summary_retry_used_list) if summary_retry_used_list else 0.0
            ),
            "validation/workflow/valid_rate": np.mean(workflow_valid_list),
            "validation/outcome/em_aggregate": np.mean(final_em_list),
            "validation/outcome/optimization_reward_after_constraints": np.mean(final_reward_list),
        }
        if self._plan_format() == "subgoal":
            test_reward_metrics.update(subgoal_summary_metrics("validation", subgoal_lists))
        for data_source, values in em_by_source.items():
            source_key = re.sub(r'[^a-z0-9]+', '_', data_source.casefold()).strip('_') or 'unknown'
            test_reward_metrics[f"validation/outcome/em_by_dataset/{source_key}"] = np.mean(values)
            test_reward_metrics[
                f"validation/outcome/optimization_reward_by_dataset/{source_key}"
            ] = np.mean(reward_by_source[data_source])
        for agent_name in ['PlanningAgent', 'QueryRewriteAgent', 'ReasonerAgent', 'AnswerSummarizationAgent', 'AnswerGenerationAgent']:
            values = record_metrics_batch['times'][agent_name]
            if values:
                test_reward_metrics[f"validation/agent_calls/{agent_name}"] = np.mean(values)

        return batch, test_reward_metrics

